def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_def = 0
    my_def = 0
    for m, o in history:
        if o == 'D':
            opp_def += 1
        if m == 'D':
            my_def += 1

    if opp_def == 0:
        if my_def == 0:
            if n == 10:
                return 'D'
            return 'C'
        elif my_def == 1:
            if history[-1][0] == 'D':
                return 'C'
            else:
                return 'D'
        else:
            return 'D'

    if opp_def == n:
        return 'D'

    if opp_def > n * 0.6:
        if history[-1][1] == 'C':
            return 'C'
        return 'D'

    last_opp = history[-1][1]
    last_me = history[-1][0]

    recent_my_def = False
    for i in range(max(0, n - 2), n):
        if history[i][0] == 'D':
            recent_my_def = True
            break

    if last_opp == 'D':
        if recent_my_def:
            return 'C'
        else:
            return 'D'
    else:
        return 'C'
